@php($t = trans('asic-secretariat.announcements_page'))
@extends('layouts.portal', ['role' => 'secretariat', 'roleName' => $t['title'], 'nav' => $secNav, 'title' => $t['title']])

@section('content')
<main class="space-y-5" x-data="{
    i18n: @js($t),
    tab: 'announcements', events: [], rows: [], loading: true, saving: false, error: '', formError: '', modal: false, editing: null,
    announcement: { id_event: '', judul: '', isi_pengumuman: '', status: 'Draft', tanggal_publikasi: '' },
    channel: { id_event: '', nama_kanal: '', jenis_kanal: 'WhatsApp', url: '', status: 'Aktif' },
    async init() { const e = await window.asicApi.get('/api/content/events', { per_page: 100 }); this.events = e.data?.data || []; await this.load(); },
    async load() {
        this.loading = true; this.error = '';
        const endpoint = this.tab === 'announcements' ? '/api/content/announcements' : '/api/content/communication-channels';
        const response = await window.asicApi.get(endpoint, { per_page: 100 });
        this.loading = false;
        if (!response.ok) { this.error = response.error || i18n.load_failed; return; }
        this.rows = response.data?.data || [];
    },
    resetForm() { this.editing = null; this.formError = ''; this.announcement = { id_event: this.events[0]?.id_event || '', judul: '', isi_pengumuman: '', status: 'Draft', tanggal_publikasi: '' }; this.channel = { id_event: this.events[0]?.id_event || '', nama_kanal: '', jenis_kanal: 'WhatsApp', url: '', status: 'Aktif' }; this.modal = true; },
    edit(row) { this.editing = this.tab === 'announcements' ? row.id_announcement : row.id_channel; this.formError = ''; if (this.tab === 'announcements') this.announcement = { id_event: row.id_event, judul: row.judul, isi_pengumuman: row.isi_pengumuman, status: row.status, tanggal_publikasi: row.tanggal_publikasi ? row.tanggal_publikasi.slice(0,16) : '' }; else this.channel = { id_event: row.id_event, nama_kanal: row.nama_kanal, jenis_kanal: row.jenis_kanal, url: row.url, status: row.status }; this.modal = true; },
    async save() { this.saving = true; this.formError = ''; const isAnn = this.tab === 'announcements'; const payload = isAnn ? { ...this.announcement } : { ...this.channel }; if (isAnn && !payload.tanggal_publikasi) payload.tanggal_publikasi = null; const root = isAnn ? '/api/content/announcements' : '/api/content/communication-channels'; const url = this.editing ? root + '/' + this.editing : root; const result = this.editing ? await window.asicApi.patch(url, payload) : await window.asicApi.post(url, payload); this.saving = false; if (!result.ok) { this.formError = result.error || Object.values(result.errors || {}).flat().join(' '); return; } this.modal = false; await this.load(); },
    async remove(row) { const id = this.tab === 'announcements' ? row.id_announcement : row.id_channel; if (!confirm(i18n.confirm_delete)) return; const root = this.tab === 'announcements' ? '/api/content/announcements/' : '/api/content/communication-channels/'; const result = await window.asicApi.delete(root + id); if (!result.ok) { this.error = result.error || i18n.delete_failed; return; } await this.load(); }
}">
