    <section class="grid gap-3 sm:grid-cols-3"><article class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant" x-text="tab==='announcements' ? i18n.total_announcements : i18n.total_channels"></p><strong class="mt-1 block text-2xl" x-text="rows.length"></strong></article><article x-show="tab==='announcements'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">{{ $t['statuses']['Draft'] }}</p><strong class="mt-1 block text-2xl" x-text="rows.filter(row => row.status === 'Draft').length"></strong></article><article x-show="tab==='announcements'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">{{ $t['published'] }}</p><strong class="mt-1 block text-2xl" x-text="rows.filter(row => row.status === 'Dipublikasikan').length"></strong></article><article x-show="tab==='channels'" class="rounded-xl border border-surface-container-high bg-surface-container-lowest p-4"><p class="text-xs uppercase text-on-surface-variant">{{ $t['active_channels'] }}</p><strong class="mt-1 block text-2xl" x-text="rows.filter(row => row.status === 'Aktif').length"></strong></article></section>
    <div class="flex gap-2"><button @click="tab='announcements'; load()" :class="tab==='announcements' ? 'bg-primary text-white' : 'bg-surface-container'" class="rounded-lg px-4 py-2 text-sm">{{ $t['tab_announcements'] }}</button><button @click="tab='channels'; load()" :class="tab==='channels' ? 'bg-primary text-white' : 'bg-surface-container'" class="rounded-lg px-4 py-2 text-sm">{{ $t['tab_channels'] }}</button></div>
