    <div x-show="modal" x-cloak class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4" @click.self="modal=false"><section class="w-full max-w-xl space-y-4 rounded-2xl bg-white p-6"><h2 class="text-lg font-bold" x-text="editing ? i18n.edit_title : i18n.add"></h2><p x-show="formError" x-text="formError" role="alert" class="text-sm text-error"></p><form @submit.prevent="save()" class="space-y-3"><template x-if="tab==='announcements'"><label class="block space-y-1 text-sm">{{ $t['col_event'] }}<select required x-model="announcement.id_event" class="w-full rounded-lg border-surface-container-highest"><template x-for="event in events" :key="event.id_event"><option :value="event.id_event" x-text="event.nama_event"></option></template></select></label></template><template x-if="tab==='channels'"><label class="block space-y-1 text-sm">{{ $t['col_event'] }}<select required x-model="channel.id_event" class="w-full rounded-lg border-surface-container-highest"><template x-for="event in events" :key="event.id_event"><option :value="event.id_event" x-text="event.nama_event"></option></template></select></label></template><template x-if="tab==='announcements'"><div class="space-y-3"><label class="block space-y-1 text-sm">{{ $t['title_field'] }}<input required maxlength="150" x-model="announcement.judul" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">{{ $t['body'] }}<textarea required x-model="announcement.isi_pengumuman" class="w-full rounded-lg border-surface-container-highest"></textarea></label><label class="block space-y-1 text-sm">{{ $t['col_status'] }}<select x-model="announcement.status" class="w-full rounded-lg border-surface-container-highest"><option value="Draft">{{ $t['statuses']['Draft'] }}</option><option value="Dipublikasikan">{{ $t['statuses']['Dipublikasikan'] }}</option></select></label><label class="block space-y-1 text-sm">{{ $t['schedule'] }}<input type="datetime-local" x-model="announcement.tanggal_publikasi" class="w-full rounded-lg border-surface-container-highest"></label></div></template><template x-if="tab==='channels'"><div class="space-y-3"><label class="block space-y-1 text-sm">{{ $t['channel_name'] }}<input required x-model="channel.nama_kanal" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">{{ $t['type'] }}<select x-model="channel.jenis_kanal" class="w-full rounded-lg border-surface-container-highest"><option>WhatsApp</option><option>Google Group</option><option>Telegram</option><option value="Lainnya">{{ $t['other'] }}</option></select></label><label class="block space-y-1 text-sm">URL<input required type="url" x-model="channel.url" class="w-full rounded-lg border-surface-container-highest"></label><label class="block space-y-1 text-sm">{{ $t['col_status'] }}<select x-model="channel.status" class="w-full rounded-lg border-surface-container-highest"><option value="Aktif">{{ $t['statuses']['Aktif'] }}</option><option value="Nonaktif">{{ $t['statuses']['Nonaktif'] }}</option></select></label></div></template><div class="flex justify-end gap-2"><button type="button" @click="modal=false" class="rounded-lg border px-4 py-2 text-sm">{{ $t['cancel'] }}</button><button :disabled="saving" class="rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-white" x-text="saving ? i18n.saving : i18n.save"></button></div></form></section></div>
</main>
